const feeds = [
  { name: 'The Hindu TN', url: 'https://www.thehindu.com/news/national/tamil-nadu/feeder/default.rss' },
  { name: 'Times of India', url: 'https://timesofindia.indiatimes.com/rssfeedstopstories.cms' },
  { name: 'New Indian Express TN', url: 'https://www.newindianexpress.com/states/tamil-nadu/rssfeed/' },
  { name: 'Dinamalar', url: 'https://www.dinamalar.com/rss/news.xml' },
  { name: 'Dinakaran', url: 'https://www.dinakaran.com/rss/news.xml' }
];

function clean(s) {
  return s.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#039;/g, "'").replace(/\s+/g, ' ').trim();
}

function extractArticles(xml, source, limit) {
  const articles = [];
  const itemRe = /<item>([\s\S]*?)<\/item>/gi;
  let m;
  while ((m = itemRe.exec(xml)) !== null && articles.length < limit) {
    const block = m[1];
    const titleM = block.match(/<title[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/i);
    const title = titleM ? clean(titleM[1]) : '';
    if (title.length <= 20) continue;
    let link = '';
    const linkM = block.match(/<link[^>]*>\s*(https?:\/\/[^\s<]+)/i);
    if (linkM) link = linkM[1].trim();
    let imageUrl = '';
    const t1 = block.match(/<media:thumbnail[^>]+url="([^"]+)"/i);
    const t2 = block.match(/<media:content[^>]+url="([^"]+\.(?:jpg|jpeg|png|webp)[^"]*)"/i);
    const t3 = block.match(/<enclosure[^>]+url="([^"]+\.(?:jpg|jpeg|png|webp))"/i);
    if (t1) imageUrl = t1[1];
    else if (t2) imageUrl = t2[1];
    else if (t3) imageUrl = t3[1];
    if (!imageUrl) {
      const descM = block.match(/<description[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/i);
      if (descM) {
        const imgM = descM[1].match(/<img[^>]+src="([^"]+\.(?:jpg|jpeg|png|webp)[^"]*)"/i);
        if (imgM) imageUrl = imgM[1];
      }
    }
    articles.push({ title, link, imageUrl, source });
  }
  return articles;
}

let allArticles = [];

for (const feed of feeds) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: feed.url,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; n8n-bot/1.0)', 'Accept': 'application/rss+xml, application/xml, text/xml, */*' },
      returnFullResponse: false,
      timeout: 15000
    });
    const xml = typeof res === 'string' ? res : JSON.stringify(res);
    allArticles = allArticles.concat(extractArticles(xml, feed.name, 5));
  } catch (err) { /* skip unavailable feed */ }
}

return [{ json: { articles: allArticles } }];

const articles = $input.first().json.articles || [];
const top10 = articles.slice(0, 10);
return [{ json: { articlesWithImages: top10 } }];

const token = 'YOUR_BOT_TOKEN';

const chatId = '8113726432';
const articles = $('Filter Top 10').first().json.articlesWithImages || [];

function escHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const now = new Date();
const session = now.getUTCHours() < 14 ? '🌅 Morning' : '🌆 Evening';
const dateStr = now.toLocaleDateString('en-IN', {
  timeZone: 'Asia/Kolkata', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const header = '📰 <b>TN News — ' + session + '</b>\n' + dateStr;

if (articles.length === 0) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/sendMessage',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, text: header + '\n\n⚠️ No articles with images found.', parse_mode: 'HTML' }),
    timeout: 15000
  });
  return [{ json: { status: 'no articles' } }];
}

// 1. Send text digest with all headlines and links
const lines = [header, ''];
articles.forEach((a, i) => {
  const t = escHtml(a.title);
  lines.push((i + 1) + '. ' + (a.link ? '<a href="' + a.link + '">' + t + '</a>' : t) + '\n   📰 <i>' + escHtml(a.source) + '</i>');
});
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: chatId, text: lines.join('\n'), parse_mode: 'HTML', disable_web_page_preview: true }),
  timeout: 15000
});

return [{ json: { status: 'done', count: articles.length } }];
